	@Test
	void defaultNoSyncCommitForcesDictionaryThenTriplesBeforePublication(@TempDir Path directory) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig();
		assertFalse(config.getForceSync());
		LmdbStore store = new LmdbStore(directory.resolve("live").toFile(), config);
		store.init();
		var events = new CopyOnWriteArrayList<String>();
		try {
			Path backups = directory.resolve("backups");
			BackupResult full = store.getBackupService()
					.createBackup(
							BackupRequest.builder(backups, BackupType.FULL).build());
			store.getBackingStore().valueStore().setBeforeBackupSync(() -> events.add("values"));
			store.getBackingStore().getTripleStore().setBeforeBackupSync(() -> events.add("triples"));
			store.getBackingStore().backupPublisher().setBeforePublication(() -> events.add("publication"));
			add(store, statement("durability", "default-nosync"));
			store.getBackupService()
					.createBackup(BackupRequest.builder(backups, BackupType.INCREMENTAL)
							.sinceTransactionId(full.getEndTransactionId())
							.build());
			assertEquals(List.of("values", "values", "triples", "publication"), events);
		} finally {
			store.shutDown();
		}
	}

