	private static void crashAndRecover(Path directory, String boundary) throws Exception {
		Path live = directory.resolve("live");
		Path backups = directory.resolve("backups");
		LmdbStore initial = new LmdbStore(live.toFile(), new LmdbStoreConfig().setForceSync(false));
		initial.init();
		BackupResult full;
		try {
			full = initial.getBackupService().createBackup(BackupRequest.builder(backups, BackupType.FULL).build());
		} finally {
			initial.shutDown();
		}
		Path output = directory.resolve("crash-child.log");
		Process child = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
				"-ea", "-cp", System.getProperty("surefire.test.class.path", System.getProperty("java.class.path")),
				LmdbPostCommitPublicationTest.class.getName(), live.toString(), boundary)
						.redirectErrorStream(true)
						.redirectOutput(output.toFile())
						.start();
		try {
			assertTrue(child.waitFor(20, TimeUnit.SECONDS), () -> "Crash child did not finish: " + output);
			assertEquals(0, child.exitValue(), () -> "Crash child failed: " + output);
		} finally {
			if (child.isAlive()) {
				child.destroyForcibly();
				assertTrue(child.waitFor(10, TimeUnit.SECONDS));
			}
		}
		Path log = backups.resolve("txlog").resolve(logName(full.getEndTransactionId() + 1));
		assertEquals(boundary.equals("before-acknowledgement"), Files.exists(log));
		LmdbStore recovered = new LmdbStore(live.toFile(), new LmdbStoreConfig().setForceSync(false));
		recovered.init();
		try {
			BackupResult incremental = recovered.getBackupService()
					.createBackup(
							BackupRequest.builder(backups, BackupType.INCREMENTAL)
									.sinceTransactionId(full.getEndTransactionId())
									.build());
			assertEquals(full.getEndTransactionId() + 1, incremental.getEndTransactionId());
			try (SailConnection connection = recovered.getConnection()) {
				assertEquals(1L, connection.size());
			}
		} finally {
			recovered.shutDown();
		}
		try (var files = Files.list(live.resolve(PostCommitBackupPublisher.DIRECTORY))) {
			assertEquals(0, files.filter(path -> path.getFileName().toString().endsWith(".stage")).count());
		}
	}

	public static void main(String[] arguments) throws Exception {
		LmdbStore store = new LmdbStore(Path.of(arguments[0]).toFile(), new LmdbStoreConfig().setForceSync(false));
		store.init();
		Runnable crash = () -> Runtime.getRuntime().halt(0);
		if (arguments[1].equals("before-journal")) {
			store.getBackingStore().backupPublisher().setBeforePublication(crash);
		} else {
			store.getBackingStore().backupPublisher().setBeforeAcknowledgement(crash);
		}
		add(store, statement("crashed", "committed"));
		// Only the actual post-release worker can terminate this child at the selected durable boundary.
		new CountDownLatch(1).await();
	}

	@Test
	void abortedStageIsNotMistakenForLaterReusedBoundary(@TempDir Path directory) throws Exception {
		Path live = directory.resolve("live");
		Path backups = directory.resolve("backups");
		LmdbStore store = new LmdbStore(live.toFile());
		store.init();
		BackupResult full;
		try {
			full = store.getBackupService().createBackup(BackupRequest.builder(backups, BackupType.FULL).build());
			store.getBackingStore().getTripleStore().beforePhysicalCommitForTest = () -> {
				throw new SailException("Abort after durable outbox preparation");
			};
			assertThrows(SailException.class, () -> add(store, statement("aborted", "discard")));
			store.getBackingStore().getTripleStore().beforePhysicalCommitForTest = null;
			add(store, statement("committed", "keep"));
		} finally {
			store.getBackingStore().getTripleStore().beforePhysicalCommitForTest = null;
			store.shutDown();
		}
		LmdbStore reopened = new LmdbStore(live.toFile());
		reopened.init();
		try {
			BackupResult incremental = reopened.getBackupService()
					.createBackup(
							BackupRequest.builder(backups, BackupType.INCREMENTAL)
									.sinceTransactionId(full.getEndTransactionId())
									.build());
			assertEquals(full.getEndTransactionId() + 1, incremental.getEndTransactionId());
			try (var input = new GZIPInputStream(Files.newInputStream(
					backups.resolve("txlog").resolve(logName(incremental.getEndTransactionId()))))) {
				var records = LmdbBackupDeltaCodec.read(input);
				assertEquals(1, records.size());
				assertEquals("urn:committed", records.getFirst().getStatement().getSubject().stringValue());
			}
		} finally {
			reopened.shutDown();
		}
	}

	@Test
	void blockedPublisherAllowsOrderedCommitsAndCompactSnapshot(@TempDir Path directory) throws Exception {
		Path backups = directory.resolve("backups");
		LmdbStore store = new LmdbStore(directory.resolve("live").toFile());
		store.init();
		ExecutorService tasks = Executors.newFixedThreadPool(2);
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		try {
			BackupResult full = store.getBackupService()
					.createBackup(
							BackupRequest.builder(backups, BackupType.FULL).build());
			store.getBackingStore().backupPublisher().setBeforePublication(() -> {
				entered.countDown();
				await(release);
			});
			Statement first = statement("first", "old");
			Statement second = statement("second", "new");
			tasks.submit(() -> add(store, first)).get(10, TimeUnit.SECONDS);
			assertTrue(entered.await(10, TimeUnit.SECONDS));
			long firstTransaction = store.getBackingStore().getCurrentCommittedTxnId();
			tasks.submit(() -> {
				try (SailConnection connection = store.getConnection()) {
					connection.begin();
					connection.removeStatements(first.getSubject(), first.getPredicate(), first.getObject());
					connection.addStatement(second.getSubject(), second.getPredicate(), second.getObject());
					connection.commit();
				}

			}).get(10, TimeUnit.SECONDS);
			long secondTransaction = store.getBackingStore().getCurrentCommittedTxnId();
			Path snapshot = directory.resolve("snapshot");
			assertEquals(secondTransaction, tasks.submit(
					() -> store.getBackingStore().createOnlineSnapshot(snapshot, true, () -> {
					})).get(10, TimeUnit.SECONDS));
			assertFalse(Files.exists(backups.resolve("txlog").resolve(logName(secondTransaction))));
			release.countDown();
			BackupResult incremental = store.getBackupService()
					.createBackup(
							BackupRequest.builder(backups, BackupType.INCREMENTAL)
									.sinceTransactionId(full.getEndTransactionId())
									.build());
			assertEquals(secondTransaction, incremental.getEndTransactionId());
			try (var input = new GZIPInputStream(new BufferedInputStream(
					Files.newInputStream(backups.resolve("txlog").resolve(logName(secondTransaction)))))) {
				var journal = LmdbBackupDeltaCodec.readJournal(input);
				assertEquals(firstTransaction, journal.previousTransactionId());
				assertEquals(2, journal.records().size());
				assertFalse(journal.records().get(0).isAddition());
				assertTrue(journal.records().get(1).isAddition());
			}
			// Copied state is its own baseline, not a copy of the source's unfinished publication work.
			LmdbStore copy = new LmdbStore(snapshot.toFile());
			copy.init();
			try (SailConnection connection = copy.getConnection()) {
				assertEquals(1L, connection.size());
				assertTrue(
						connection.hasStatement(second.getSubject(), second.getPredicate(), second.getObject(), false));
			} finally {
				copy.shutDown();
			}
		} finally {
			release.countDown();
			tasks.shutdownNow();
			assertTrue(tasks.awaitTermination(10, TimeUnit.SECONDS));
			store.shutDown();
		}
	}

	@Test
	void spilledRecordsRemainOwnedAfterFollowingCommit(@TempDir Path directory) throws Exception {
		LmdbStore store = new LmdbStore(directory.resolve("live").toFile());
		Path backups = directory.resolve("backups");
		store.init();
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		try {
			BackupResult full = store.getBackupService()
					.createBackup(
							BackupRequest.builder(backups, BackupType.FULL).build());
			store.getBackingStore().backupPublisher().setBeforePublication(() -> {
				entered.countDown();
				await(release);
			});
			String first = "first".repeat(40_000);
			String second = "second".repeat(40_000);
			add(store, statement("large-first", first));
			assertTrue(entered.await(10, TimeUnit.SECONDS));
			long firstTransaction = store.getBackingStore().getCurrentCommittedTxnId();
			add(store, statement("large-second", second));
			long secondTransaction = store.getBackingStore().getCurrentCommittedTxnId();
			release.countDown();
			store.getBackupService()
					.createBackup(BackupRequest.builder(backups, BackupType.INCREMENTAL)
							.sinceTransactionId(full.getEndTransactionId())
							.build());
			for (long transaction : new long[] { firstTransaction, secondTransaction }) {
				try (var input = new GZIPInputStream(Files.newInputStream(
						backups.resolve("txlog").resolve(logName(transaction))))) {
					var records = LmdbBackupDeltaCodec.read(input);
					assertEquals(1, records.size());
					assertEquals(transaction == firstTransaction ? first : second,
							records.getFirst().getStatement().getObject().stringValue());
				}
			}
		} finally {
			release.countDown();
			store.shutDown();
		}
	}

