	@Test
	void publicationFailureStopsLaterDeltasAndSurfacesGap(@TempDir Path directory) throws Exception {
		Path backups = directory.resolve("backups");
		Path live = directory.resolve("live");
		LmdbStore store = new LmdbStore(live.toFile());
		store.init();
		BackupResult full;
		long target;
		try {
			full = store.getBackupService().createBackup(BackupRequest.builder(backups, BackupType.FULL).build());
			Files.writeString(backups.resolve("txlog"), "blocked");
			add(store, statement("first", "one"));
			add(store, statement("second", "two"));
			target = store.getBackingStore().getCurrentCommittedTxnId();
			SailException failure = assertThrows(SailException.class, () -> store.getBackupService()
					.createBackup(
							BackupRequest.builder(backups, BackupType.INCREMENTAL)
									.sinceTransactionId(full.getEndTransactionId())
									.build()));
			assertTrue(failure.getMessage().contains("Missing committed transaction journal at"));
			assertTrue(store.getBackupService().getStatus().getLastFailureMessage().isPresent());
		} finally {
			store.shutDown();
		}
		Files.delete(backups.resolve("txlog"));
		LmdbStore reopened = new LmdbStore(live.toFile());
		reopened.init();
		try {
			assertEquals(target, reopened.getBackupService()
					.createBackup(
							BackupRequest.builder(backups, BackupType.INCREMENTAL)
									.sinceTransactionId(full.getEndTransactionId())
									.build())
					.getEndTransactionId());
		} finally {
			reopened.shutDown();
		}
		// A second reopen must not attempt to republish acknowledged records or lose its baseline.
		LmdbStore again = new LmdbStore(live.toFile());
		again.init();
		try {
			assertEquals(target, again.getBackupService()
					.createBackup(
							BackupRequest.builder(backups, BackupType.INCREMENTAL)
									.sinceTransactionId(full.getEndTransactionId())
									.build())
					.getEndTransactionId());
		} finally {
			again.shutDown();
		}
	}

	@Test
	void shutdownDrainsPublisherBeforeClosingService(@TempDir Path directory) throws Exception {
		Path backups = directory.resolve("backups");
		LmdbStore store = new LmdbStore(directory.resolve("live").toFile());
		store.init();
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		ExecutorService task = Executors.newSingleThreadExecutor();
		try {
			store.getBackupService().createBackup(BackupRequest.builder(backups, BackupType.FULL).build());
			store.getBackingStore().backupPublisher().setBeforePublication(() -> {
				entered.countDown();
				await(release);
			});
			add(store, statement("shutdown", "durable"));
			long target = store.getBackingStore().getCurrentCommittedTxnId();
			assertTrue(entered.await(10, TimeUnit.SECONDS));
			var shutdown = task.submit(store::shutDown);
			release.countDown();
			shutdown.get(10, TimeUnit.SECONDS);
			assertTrue(Files.isRegularFile(backups.resolve("txlog").resolve(logName(target))));
		} finally {
			release.countDown();
			task.shutdownNow();
			assertTrue(task.awaitTermination(10, TimeUnit.SECONDS));
			store.shutDown();
		}
	}

	private static String logName(long transaction) {
		return String.format("txn-%020d.delta.gz", transaction);
	}

	private static Statement statement(String subject, String label) {
		var vf = SimpleValueFactory.getInstance();
		return vf.createStatement(vf.createIRI("urn:" + subject), RDF.TYPE, vf.createLiteral(label));
	}

	private static void add(LmdbStore store, Statement statement) {
		try (SailConnection connection = store.getConnection()) {
			connection.begin();
			connection.addStatement(statement.getSubject(), statement.getPredicate(), statement.getObject());
			connection.commit();
		}
	}

	private static void await(CountDownLatch latch) {
		try {
			if (!latch.await(20, TimeUnit.SECONDS)) {
				throw new AssertionError("Publication release was not signalled");
			}
		} catch (InterruptedException failure) {
			Thread.currentThread().interrupt();
			throw new AssertionError(failure);
		}
	}

	@Test
	void recoversCommittedDeltaAfterPublicationFailure(@TempDir Path directory) throws Exception {
		Path live = directory.resolve("live");
		Path backups = directory.resolve("backups");
		LmdbStore store = new LmdbStore(live.toFile());
		store.init();
		BackupResult full;
		long target;
		try {
			full = store.getBackupService().createBackup(BackupRequest.builder(backups, BackupType.FULL).build());
			Files.writeString(backups.resolve("txlog"), "not a directory");
			var vf = SimpleValueFactory.getInstance();
			try (SailConnection connection = store.getConnection()) {
				connection.begin();
				connection.addStatement(vf.createIRI("urn:recovered"), RDF.TYPE, vf.createIRI("urn:Thing"));
				connection.setNamespace("recovered", "urn:recovered:");
				connection.commit();
			}
			target = store.getBackingStore().getCurrentCommittedTxnId();
		} finally {
			store.shutDown();
		}
		Files.delete(backups.resolve("txlog"));
		LmdbStore reopened = new LmdbStore(live.toFile());
		reopened.init();
		try {
			BackupResult incremental = reopened.getBackupService()
					.createBackup(
							BackupRequest.builder(backups, BackupType.INCREMENTAL)
									.sinceTransactionId(full.getEndTransactionId())
									.build());
			assertEquals(target, incremental.getEndTransactionId());
			Path restored = reopened.getBackupService()
					.restore(new PointInTimeRestoreRequest(backups,
							directory.resolve("restored"), target, true));
			LmdbStore restoredStore = new LmdbStore(restored.toFile());
			restoredStore.init();
			try (SailConnection connection = restoredStore.getConnection()) {
				assertEquals(1L, connection.size());
				assertEquals("urn:recovered:", connection.getNamespace("recovered"));
				assertTrue(connection.hasStatement(SimpleValueFactory.getInstance().createIRI("urn:recovered"),
						RDF.TYPE, null, false));
			} finally {
				restoredStore.shutDown();
			}
		} finally {
			reopened.shutDown();
		}
	}
